INSERT INTO public.parts (id, numero, nombre, nombre_en, seccion, descripcion, tiempo_sugerido_minutos, icono) VALUES
  (1, 1, 'Fotografías', 'Photographs', 'listening', 'Observa una fotografía y escucha 4 afirmaciones en audio. Elige la que describe con precisión la imagen.', 5, 'Camera'),
  (2, 2, 'Pregunta - Respuesta', 'Question - Response', 'listening', 'Solo audio sin texto en pantalla. Escuchas una pregunta o afirmación y tres posibles respuestas habladas (A, B, C).', 10, 'HelpCircle'),
  (3, 3, 'Conversaciones', 'Conversations', 'listening', 'Diálogos entre 2 o 3 personas de ámbito profesional o comercial. Cada audio genera 3 preguntas vinculadas.', 15, 'Users'),
  (4, 4, 'Charlas Breves', 'Short Talks', 'listening', 'Monólogos profesionales como anuncios públicos, reportes meteorológicos o mensajes de voz, con 3 preguntas.', 15, 'Radio'),
  (5, 5, 'Oraciones Incompletas', 'Incomplete Sentences', 'reading', 'Enunciados con un espacio en blanco y 4 opciones gramaticales o léxicas. Evalúa vocabulario y estructuras formales.', 15, 'FileEdit'),
  (6, 6, 'Texto Completado', 'Text Completion', 'reading', 'Documentos empresariales breves (correos, notas, cartas) con 4 espacios en blanco que deben rellenarse coherentemente.', 12, 'FileText'),
  (7, 7, 'Comprensión de Lectura', 'Reading Comprehension', 'reading', 'Pasajes individuales, dobles y triples (artículos, mensajes de texto, formularios, horarios) con múltiples preguntas.', 48, 'BookOpen')
INSERT INTO public.passages (id, part_id, tipo, titulo, contenido_url, contenido_texto, segundo_texto, tercer_texto, transcript_oculto) VALUES
  ('p1-01', 1, 'image_and_audio', 'Executive Boardroom Meeting', 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) The participants are packing up their briefcases. (B) A presenter is pointing to a slide on the projection screen. (C) The conference table is completely empty. (D) Several people are leaving through the exit door.'),
  ('p1-02', 1, 'image_and_audio', 'Customer Service Counter', 'https://images.unsplash.com/photo-1556742049-0a67c5574f73?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) A cashier is handing a receipt to a customer. (B) Shelves are being restocked in the warehouse. (C) The store clerk is locking the front entrance. (D) Customers are waiting outside in a long queue.'),
  ('p1-03', 1, 'image_and_audio', 'Logistics Distribution Warehouse', 'https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) Cardboard boxes are stacked high on wooden pallets. (B) A forklift is being repaired on the street. (C) Workers are loading luggage onto an airplane. (D) The shipping dock has been abandoned.'),
  ('p1-04', 1, 'image_and_audio', 'Modern Architecture Construction Site', 'https://images.unsplash.com/photo-1541888946425-d0fbb186c5f7?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) The architects are reviewing blueprints on a table. (B) Heavy machinery is parked in front of the building frame. (C) Pedestrians are walking across a pedestrian bridge. (D) A crane is dismantling a wooden structure.'),
  ('p1-05', 1, 'image_and_audio', 'Corporate Open Space Office', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) Office chairs are neatly arranged around modern workstations. (B) Technicians are replacing the overhead light bulbs. (C) The carpet is being cleaned with vacuum cleaners. (D) The blinds have been completely lowered over every window.'),
  ('p1-06', 1, 'image_and_audio', 'Airport Departure Terminal', 'https://images.unsplash.com/photo-1530521954074-e64f6810b32d?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) Travelers are pulling suitcases through the concourse. (B) Planes are refueling on the tarmac. (C) Passengers are boarding the aircraft via a stairway. (D) Flight attendants are serving meals in the cabin.'),
  ('p1-07', 1, 'image_and_audio', 'Outdoor Sidewalk Cafe', 'https://images.unsplash.com/photo-1554118811-1e0d58224f24?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) Patio umbrellas shade several small tables. (B) A waiter is washing dishes in the kitchen. (C) Cars are parked directly on the dining patio. (D) Customers are ordering at an indoor drive-through window.'),
  ('p1-08', 1, 'image_and_audio', 'Scientific Research Laboratory', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) A scientist in a white lab coat is examining a specimen through a microscope. (B) A medical doctor is performing surgery in an operating room. (C) Glass beakers are being discarded in a waste container. (D) Patients are waiting for consultations in the lobby.'),
  ('p1-09', 1, 'image_and_audio', 'Public Transportation Train Platform', 'https://images.unsplash.com/photo-1474487548417-781cb71495f3?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) Commuters are standing behind the yellow safety line on the platform. (B) A train driver is inspecting the locomotive engine. (C) Luggage carts are blocking the railway tracks. (D) Tickets are being sold inside the subway car.'),
  ('p1-10', 1, 'image_and_audio', 'Retail Clothing Boutique', 'https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) Garments are hanging neatly on metal display racks. (B) A tailor is measuring fabric with a tape measure. (C) Mannequins are being unpacked from shipping crates. (D) Customers are trying on shoes in the fitting room.'),
  ('p1-11', 1, 'image_and_audio', 'Printing Room Office #11', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) A worker is replacing the paper tray in a copy machine. (B) The computer monitor is unplugged. (C) A delivery driver is carrying a box upstairs. (D) A delivery driver is carrying a box upstairs.'),
  ('p1-12', 1, 'image_and_audio', 'Hotel Reception Lobby #12', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) Luggage has been left in the parking lot. (B) The elevators are under maintenance. (C) A receptionist is speaking to guests at the front desk. (D) Keys are hanging behind the locked door.'),
  ('p1-13', 1, 'image_and_audio', 'Supermarket Grocery Aisle #13', 'https://images.unsplash.com/photo-1578916171728-46686eac8d58?auto=format&fit=crop&w=800&q=80', NULL, NULL, NULL, '(A) A shopper is pushing an overloaded forklift. (B) Fresh produce is displayed in wooden crates. (C) Carts are blocking the checkout counter. (D) Carts are blocking the checkout counter.'),
