INSERT INTO public.questions (id, passage_id, part_id, numero_pregunta, enunciado, opciones, respuesta_correcta, explicacion, subtema, dificultad, audio_script) VALUES
  ('q1-01', 'p1-01', 1, 1, 'Look at the image and choose the statement that best describes what you see.', '[{"key":"A","text":"The participants are packing up their briefcases."},{"key":"B","text":"A presenter is pointing to a slide on the projection screen."},{"key":"C","text":"The conference table is completely empty."},{"key":"D","text":"Several people are leaving through the exit door."}]'::jsonb, 'B', 'La opción B describe con exactitud la acción principal: el orador está señalando la pantalla de proyección ante el equipo.', 'Acciones en sala de conferencias', 'easy', 'Number 1. Look at the image marked number 1. (A) The participants are packing up their briefcases. (B) A presenter is pointing to a slide on the projection screen. (C) The conference table is completely empty. (D) Several people are leaving through the exit door.'),
  ('q1-02', 'p1-02', 1, 2, 'Look at the image and choose the statement that best describes what you see.', '[{"key":"A","text":"A cashier is handing a receipt to a customer."},{"key":"B","text":"Shelves are being restocked in the warehouse."},{"key":"C","text":"The store clerk is locking the front entrance."},{"key":"D","text":"Customers are waiting outside in a long queue."}]'::jsonb, 'A', 'La opción A describe la acción observable: el empleado en caja entrega un comprobante o recibo a la persona frente al mostrador.', 'Transacciones comerciales y servicio al cliente', 'easy', 'Number 2. Look at the image marked number 2. (A) A cashier is handing a receipt to a customer. (B) Shelves are being restocked in the warehouse. (C) The store clerk is locking the front entrance. (D) Customers are waiting outside in a long queue.'),
  ('q1-03', 'p1-03', 1, 3, 'Look at the image and choose the statement that best describes what you see.', '[{"key":"A","text":"Cardboard boxes are stacked high on wooden pallets."},{"key":"B","text":"A forklift is being repaired on the street."},{"key":"C","text":"Workers are loading luggage onto an airplane."},{"key":"D","text":"The shipping dock has been abandoned."}]'::jsonb, 'A', 'La opción A describe el estado físico de los objetos en la bodega de distribución (cajas apiladas en tarimas de madera).', 'Almacén y logística', 'medium', 'Number 3. Look at the image marked number 3. (A) Cardboard boxes are stacked high on wooden pallets. (B) A forklift is being repaired on the street. (C) Workers are loading luggage onto an airplane. (D) The shipping dock has been abandoned.'),
  ('q1-04', 'p1-04', 1, 4, 'Look at the image and choose the statement that best describes what you see.', '[{"key":"A","text":"The architects are reviewing blueprints on a table."},{"key":"B","text":"Heavy machinery is parked in front of the building frame."},{"key":"C","text":"Pedestrians are walking across a pedestrian bridge."},{"key":"D","text":"A crane is dismantling a wooden structure."}]'::jsonb, 'B', 'En la obra en construcción se aprecian maquinarias pesadas estacionadas junto a la estructura metálica del edificio.', 'Construcción y obras de infraestructura', 'medium', 'Number 4. Look at the image marked number 4. (A) The architects are reviewing blueprints on a table. (B) Heavy machinery is parked in front of the building frame. (C) Pedestrians are walking across a pedestrian bridge. (D) A crane is dismantling a wooden structure.'),
  ('q1-05', 'p1-05', 1, 5, 'Look at the image and choose the statement that best describes what you see.', '[{"key":"A","text":"Office chairs are neatly arranged around modern workstations."},{"key":"B","text":"Technicians are replacing the overhead light bulbs."},{"key":"C","text":"The carpet is being cleaned with vacuum cleaners."},{"key":"D","text":"The blinds have been completely lowered over every window."}]'::jsonb, 'A', 'La opción A refleja el estado estático de la oficina organizada con escritorios y sillas ergonómicas dispuestas ordenadamente.', 'Entorno de oficina y mobiliario', 'easy', 'Number 5. Look at the image marked number 5. (A) Office chairs are neatly arranged around modern workstations. (B) Technicians are replacing the overhead light bulbs. (C) The carpet is being cleaned with vacuum cleaners. (D) The blinds have been completely lowered over every window.'),
  ('q1-06', 'p1-06', 1, 6, 'Look at the image and choose the statement that best describes what you see.', '[{"key":"A","text":"Travelers are pulling suitcases through the concourse."},{"key":"B","text":"Planes are refueling on the tarmac."},{"key":"C","text":"Passengers are boarding the aircraft via a stairway."},{"key":"D","text":"Flight attendants are serving meals in the cabin."}]'::jsonb, 'A', 'Se observa a varios pasajeros transitando por el pasillo principal del aeropuerto llevando equipaje con ruedas.', 'Viajes de negocios y aeropuertos', 'easy', 'Number 6. Look at the image marked number 6. (A) Travelers are pulling suitcases through the concourse. (B) Planes are refueling on the tarmac. (C) Passengers are boarding the aircraft via a stairway. (D) Flight attendants are serving meals in the cabin.'),
