  ('q1-45', 'p1-45', 1, 45, 'Look at the image and choose the statement that best describes what you see.', '[{"key":"A","text":"Tourists are boarding a small ferry boat."},{"key":"B","text":"The dock is submerged in deep water."},{"key":"C","text":"Cargo containers are loaded aboard a freight vessel."},{"key":"D","text":"Fishing nets are spread out on the pier."}]'::jsonb, 'C', 'La opción C coincide exactamente con lo que muestra la imagen, evitando distractores de sonido o acciones no observables.', 'Entornos de negocios e instalaciones', 'hard', 'Number 45. Look at the image marked number 45. (A) Tourists are boarding a small ferry boat. (B) The dock is submerged in deep water. (C) Cargo containers are loaded aboard a freight vessel. (D) Fishing nets are spread out on the pier.'),
  ('q2-01', NULL, 2, 1, 'Where did you leave the contract files?', '[{"key":"A","text":"In the top drawer of my desk."},{"key":"B","text":"Yes, I signed it yesterday."},{"key":"C","text":"Around four o’clock."}]'::jsonb, 'A', 'La pregunta inicia con "Where", pidiendo una ubicación física. La opción A indica directamente el cajón del escritorio.', 'Preguntas con Where (Ubicación)', 'easy', 'Where did you leave the contract files? (A) In the top drawer of my desk. (B) Yes, I signed it yesterday. (C) Around four o’clock.'),
  ('q2-02', NULL, 2, 2, 'When will the annual financial audit begin?', '[{"key":"A","text":"For the accounting team."},{"key":"B","text":"Early next Monday morning."},{"key":"C","text":"Because of budget revisions."}]'::jsonb, 'B', '"When" solicita una indicación de tiempo o fecha; la opción B responde con el momento exacto (el próximo lunes por la mañana).', 'Preguntas con When (Tiempo)', 'easy', 'When will the annual financial audit begin? (A) For the accounting team. (B) Early next Monday morning. (C) Because of budget revisions.'),
  ('q2-03', NULL, 2, 3, 'Who is leading the marketing presentation this afternoon?', '[{"key":"A","text":"Ms. Henderson from corporate headquarters."},{"key":"B","text":"In the second floor conference room."},{"key":"C","text":"To attract international clients."}]'::jsonb, 'A', '"Who" requiere una persona o responsable. La opción A identifica con nombre y cargo a la persona.', 'Preguntas con Who (Personas)', 'easy', 'Who is leading the marketing presentation this afternoon? (A) Ms. Henderson from corporate headquarters. (B) In the second floor conference room. (C) To attract international clients.'),
  ('q2-04', NULL, 2, 4, 'Would you like to review the sales figures now or after lunch?', '[{"key":"A","text":"Let’s look at them right away."},{"key":"B","text":"Fifteen percent growth."},{"key":"C","text":"The cafeteria on the ground floor."}]'::jsonb, 'A', 'Es una pregunta de opción alternativa ("now or after lunch"). La respuesta A elige verlos de inmediato ("right away").', 'Preguntas de alternativa (Or)', 'medium', 'Would you like to review the sales figures now or after lunch? (A) Let’s look at them right away. (B) Fifteen percent growth. (C) The cafeteria on the ground floor.'),
  ('q2-05', NULL, 2, 5, 'Why hasn’t the shipment arrived yet?', '[{"key":"A","text":"There was a severe storm at the harbor."},{"key":"B","text":"Yes, twenty boxes of supplies."},{"key":"C","text":"By express courier service."}]'::jsonb, 'A', '"Why" pregunta por una causa o motivo. La opción A explica la razón del retraso (una tormenta severa en el puerto).', 'Preguntas con Why (Causas)', 'medium', 'Why hasn’t the shipment arrived yet? (A) There was a severe storm at the harbor. (B) Yes, twenty boxes of supplies. (C) By express courier service.')
INSERT INTO public.questions (id, passage_id, part_id, numero_pregunta, enunciado, opciones, respuesta_correcta, explicacion, subtema, dificultad, audio_script) VALUES
  ('q2-06', NULL, 2, 6, 'Could you help me carry these presentation displays to room 302?', '[{"key":"A","text":"Sure, let me grab the door for you."},{"key":"B","text":"No, it’s not room 302."},{"key":"C","text":"The projector is broken."}]'::jsonb, 'A', 'Es una petición de cortesía ("Could you help me...?"). La respuesta A acepta cooperar cordialmente.', 'Peticiones y ofertas de cortesía', 'easy', 'Could you help me carry these presentation displays to room 302? (A) Sure, let me grab the door for you. (B) No, it’s not room 302. (C) The projector is broken.'),
  ('q2-07', NULL, 2, 7, 'Shouldn’t we confirm the hotel reservations before booking our flights?', '[{"key":"A","text":"I already verified our rooms this morning."},{"key":"B","text":"At the downtown terminal."},{"key":"C","text":"A window seat, please."}]'::jsonb, 'A', 'Pregunta negativa ("Shouldn’t we...?"). La opción A responde indirectamente señalando que las reservas de hotel ya fueron verificadas.', 'Respuestas indirectas / Preguntas negativas', 'hard', 'Shouldn’t we confirm the hotel reservations before booking our flights? (A) I already verified our rooms this morning. (B) At the downtown terminal. (C) A window seat, please.'),
  ('q2-08', NULL, 2, 8, 'How many copies of the agenda do we need for the board meeting?', '[{"key":"A","text":"Twelve should be enough."},{"key":"B","text":"It’s on page four."},{"key":"C","text":"The printer is out of blue ink."}]'::jsonb, 'A', '"How many" pide una cantidad numérica. La opción A especifica que doce ejemplares serán suficientes.', 'Preguntas con How much / How many', 'easy', 'How many copies of the agenda do we need for the board meeting? (A) Twelve should be enough. (B) It’s on page four. (C) The printer is out of blue ink.'),
  ('q2-09', NULL, 2, 9, 'Did Mr. Tanaka approve the revised project budget?', '[{"key":"A","text":"He asked for a few minor changes first."},{"key":"B","text":"In the accounting department."},{"key":"C","text":"Yes, it costs forty dollars."}]'::jsonb, 'A', 'Pregunta de confirmación ("Did he approve...?"). La respuesta A aclara de forma realista que pidió cambios antes de aprobarlo.', 'Verificación en gestión de proyectos', 'medium', 'Did Mr. Tanaka approve the revised project budget? (A) He asked for a few minor changes first. (B) In the accounting department. (C) Yes, it costs forty dollars.'),
  ('q2-10', NULL, 2, 10, 'The air conditioning in the seminar room isn’t working.', '[{"key":"A","text":"I’ll contact building maintenance right away."},{"key":"B","text":"Yes, I conditioned my hair."},{"key":"C","text":"The seminar begins at two."}]'::jsonb, 'A', 'Es una declaración de problema (afirmación). La respuesta lógica A ofrece solucionar la incidencia llamando a mantenimiento.', 'Afirmaciones y resolución de problemas', 'medium', 'The air conditioning in the seminar room isn’t working. (A) I’ll contact building maintenance right away. (B) Yes, I conditioned my hair. (C) The seminar begins at two.'),
  ('q2-11', NULL, 2, 11, 'How long will the software installation take?', '[{"key":"A","text":"About forty-five minutes."},{"key":"B","text":"On my computer laptop."},{"key":"C","text":"Yes, it was very long."}]'::jsonb, 'A', 'La respuesta adecuada a la pregunta planteada es la opción A, evitando los típicos distractores de palabras repetidas o respuestas fuera de contexto.', 'Interacción y comunicación laboral cotidiana', 'easy', 'How long will the software installation take? (A) About forty-five minutes. (B) On my computer laptop. (C) Yes, it was very long.'),
