  ('q5-16', NULL, 5, 16, 'Prior to _______ the contractual documents, please make certain you have understood all stipulations.', '[{"key":"A","text":"sign"},{"key":"B","text":"signing"},{"key":"C","text":"signed"},{"key":"D","text":"signature"}]'::jsonb, 'B', 'Detrás de la preposición "Prior to" se debe emplear un sustantivo o gerundio ("signing").', 'Gerundios tras preposiciones', 'easy', NULL),
  ('q5-17', NULL, 5, 17, 'The client expressed extreme _______ with the promptness and accuracy of our customer service staff.', '[{"key":"A","text":"satisfaction"},{"key":"B","text":"satisfy"},{"key":"C","text":"satisfied"},{"key":"D","text":"satisfactorily"}]'::jsonb, 'A', '"Extreme" es un adjetivo que debe calificar a un sustantivo ("satisfaction").', 'Formas de palabras (Sustantivos)', 'easy', NULL),
