  ('q7-01', 'p7-01', 7, 1, 'What is the primary purpose of Samantha Hughes’ email?', '[{"key":"A","text":"To cancel an upcoming equipment lease"},{"key":"B","text":"To report incomplete contents in a recent order"},{"key":"C","text":"To request an estimate for office renovations"},{"key":"D","text":"To apply for a customer service position"}]'::jsonb, 'B', 'La autora escribe para reportar que sólo llegaron 2 de los 6 escritorios ajustables en el pedido #77419 ("only two of the six standing desk risers were included").', 'Propósito principal de correspondencia comercial', 'easy', NULL),
  ('q7-02', 'p7-01', 7, 2, 'What item was received in the full quantity ordered?', '[{"key":"A","text":"Standing desk risers"},{"key":"B","text":"Computer monitors"},{"key":"C","text":"Ergonomic task chairs"},{"key":"D","text":"Conference tables"}]'::jsonb, 'C', 'El correo especifica: "while all fifteen chairs arrived in pristine condition", lo que confirma que las 15 sillas llegaron completas.', 'Detalles específicos de inventario', 'easy', NULL),
  ('q7-03', 'p7-01', 7, 3, 'Why is Friday a critical deadline for the recipient?', '[{"key":"A","text":"The warehouse will be closed for holiday inventory"},{"key":"B","text":"The new Atlanta branch opens to staff next Monday"},{"key":"C","text":"A warranty return policy expires on Friday"},{"key":"D","text":"Company credit card statements close on Friday"}]'::jsonb, 'B', 'Se señala explícitamente: "Given that our new branch officially opens to staff next Monday, October 20th... critical that we receive the remaining four units by this Friday".', 'Comprensión de plazos y causas', 'medium', NULL),
  ('q7-04', 'p7-02', 7, 4, 'What deadline are the participants working against?', '[{"key":"A","text":"11:00 AM for staff registration"},{"key":"B","text":"1:00 PM for print approval"},{"key":"C","text":"End of day for product testing"},{"key":"D","text":"November 1st for the conference opening"}]'::jsonb, 'B', 'Liam menciona al inicio: "The printing company needs our approval before 1:00 PM today".', 'Identificación de horarios y plazos', 'easy', NULL),
  ('q7-05', 'p7-02', 7, 5, 'What error did Elena discover in the brochure mockup?', '[{"key":"A","text":"An incorrect exhibition booth number"},{"key":"B","text":"A misspelled contact email address"},{"key":"C","text":"An outdated company logo"},{"key":"D","text":"A missing pricing table"}]'::jsonb, 'B', 'Elena señala que la dirección de correo tiene un error tipográfico: "greentek.com" en vez de "greentech".', 'Detección de errores y correcciones', 'medium', NULL),
  ('q7-06', 'p7-02', 7, 6, 'What benefit does the code "EXPO20" provide?', '[{"key":"A","text":"Free airport transportation"},{"key":"B","text":"Complimentary hotel breakfast"},{"key":"C","text":"A 20% discount on conference registration"},{"key":"D","text":"Priority access to keynote speakers"}]'::jsonb, 'C', 'Liam aclara: "that code grants a 20% registration waiver until November 1st".', 'Beneficios comerciales y promociones', 'easy', NULL),
  ('q7-07', 'p7-03', 7, 7, 'What requirement is explicitly listed as strongly preferred in the job posting?', '[{"key":"A","text":"Possession of a commercial driver’s license"},{"key":"B","text":"Fluency in Spanish or Mandarin"},{"key":"C","text":"A Master of Business Administration degree"},{"key":"D","text":"Experience living abroad for ten years"}]'::jsonb, 'B', 'En el anuncio se indica: "Fluency in Spanish or Mandarin is strongly preferred".', 'Requisitos de ofertas de empleo', 'easy', NULL),
  ('q7-08', 'p7-03', 7, 8, 'Where does Mateo Morales currently work?', '[{"key":"A","text":"TransGlobal Freight Lines"},{"key":"B","text":"Great Lakes Maritime"},{"key":"C","text":"Chicago Transit Authority"},{"key":"D","text":"Midwest Intermodal Express"}]'::jsonb, 'B', 'En su carta Mateo afirma: "For the past six years, I have served as Freight Operations Specialist at Great Lakes Maritime in Cleveland".', 'Lectura cruzada de datos biográficos', 'easy', NULL),
  ('q7-09', 'p7-03', 7, 9, 'How does Mateo meet the preferred language requirement?', '[{"key":"A","text":"He studied Mandarin in Beijing"},{"key":"B","text":"He is a native bilingual speaker of English and Spanish"},{"key":"C","text":"He passed an advanced German certification exam"},{"key":"D","text":"He employs a full-time translator"}]'::jsonb, 'B', 'Mateo destaca: "as a native bilingual speaker of English and Spanish, I have regularly facilitated international customs clearances".', 'Correspondencia entre requisitos y perfil', 'medium', NULL),
  ('q7-10', 'p7-03', 7, 10, 'What software tool did Mateo use to improve dispatch efficiency?', '[{"key":"A","text":"Oracle Financials"},{"key":"B","text":"SAP Logistics"},{"key":"C","text":"Microsoft Access"},{"key":"D","text":"QuickBooks Enterprise"}]'::jsonb, 'B', 'Menciona explícitamente: "I routinely utilized SAP Logistics to optimize dispatch schedules".', 'Habilidades técnicas y software', 'medium', NULL),
  ('q7-11', 'p7-03', 7, 11, 'What is indicated about the work arrangement for the coordinator position?', '[{"key":"A","text":"It is 100% remote with no office visits required"},{"key":"B","text":"It combines onsite days with remote work"},{"key":"C","text":"It requires continuous international travel"},{"key":"D","text":"It operates only during weekend night shifts"}]'::jsonb, 'B', 'El anuncio especifica modalidad híbrida: "Hybrid: 3 days onsite, 2 days remote".', 'Condiciones de contratación', 'easy', NULL),
  ('q7-12', 'p7-12', 7, 12, 'What session did Dr. Thorne attend?', '[{"key":"A","text":"Cloud Cybersecurity"},{"key":"B","text":"AI in Supply Chains"},{"key":"C","text":"Networking Reception"},{"key":"D","text":"Opening Ceremony"}]'::jsonb, 'B', 'Dr. Thorne asistió a la sesión de las 3:15 p.m. sobre IA en cadenas de suministro.', 'Eventos profesionales y encuestas de satisfacción', 'easy', NULL),
  ('q7-13', 'p7-12', 7, 13, 'What did Dr. Thorne complain about?', '[{"key":"A","text":"Poor audio quality"},{"key":"B","text":"Short presentation duration"},{"key":"C","text":"Cold room temperature"},{"key":"D","text":"Lack of visual slides"}]'::jsonb, 'C', 'Se quejó de que el aire acondicionado estaba demasiado frío en Hall B.', 'Eventos profesionales y encuestas de satisfacción', 'easy', NULL),
  ('q7-14', 'p7-12', 7, 14, 'Where was the session held?', '[{"key":"A","text":"Hall B"},{"key":"B","text":"Hall A"},{"key":"C","text":"Garden Terrace"},{"key":"D","text":"Exhibition Pavilion"}]'::jsonb, 'A', 'El horario vincula la sesión de las 3:15 PM con Hall B.', 'Eventos profesionales y encuestas de satisfacción', 'easy', NULL),
  ('q7-15', 'p7-12', 7, 15, 'What is stated about Hall B in the schedule?', '[{"key":"A","text":"It is closed for renovations"},{"key":"B","text":"It has no video screens"},{"key":"C","text":"It is located on the rooftop"},{"key":"D","text":"It requires advance registration"}]'::jsonb, 'D', 'La nota indica que Hall B requiere registro previo por cupos limitados.', 'Eventos profesionales y encuestas de satisfacción', 'easy', NULL),
  ('q7-16', 'p7-16', 7, 16, 'What will the first 100 shoppers receive?', '[{"key":"A","text":"A tote bag and sourdough bread"},{"key":"B","text":"A $50 gift card"},{"key":"C","text":"Free cooking classes"},{"key":"D","text":"A bouquet of flowers"}]'::jsonb, 'A', 'Los primeros 100 reciben una bolsa de algodón y un pan artesanal de masa madre.', 'Comercio minorista y cupones de descuento', 'easy', NULL),
  ('q7-17', 'p7-16', 7, 17, 'What is the minimum purchase required to use the coupon?', '[{"key":"A","text":"$50"},{"key":"B","text":"$75"},{"key":"C","text":"$100"},{"key":"D","text":"$120"}]'::jsonb, 'B', 'El cupón exige una compra mínima de $75 para descontar $15.', 'Comercio minorista y cupones de descuento', 'easy', NULL)
INSERT INTO public.questions (id, passage_id, part_id, numero_pregunta, enunciado, opciones, respuesta_correcta, explicacion, subtema, dificultad, audio_script) VALUES
  ('q7-18', 'p7-16', 7, 18, 'When does the promotional coupon expire?', '[{"key":"A","text":"November 5th"},{"key":"B","text":"November 10th"},{"key":"C","text":"November 12th"},{"key":"D","text":"December 1st"}]'::jsonb, 'C', 'El texto estipula validez hasta el 12 de noviembre.', 'Comercio minorista y cupones de descuento', 'easy', NULL),
  ('q7-19', 'p7-16', 7, 19, 'Which item is not eligible for the discount?', '[{"key":"A","text":"Dairy products"},{"key":"B","text":"Fresh vegetables"},{"key":"C","text":"Bakery items"},{"key":"D","text":"Canned beans"}]'::jsonb, 'A', 'El cupón excluye explícitamente tarjetas de regalo y productos lácteos (dairy products).', 'Comercio minorista y cupones de descuento', 'easy', NULL),
  ('q7-20', 'p7-20', 7, 20, 'What is the daily maximum allowance for meals under the revised policy?', '[{"key":"A","text":"$50"},{"key":"B","text":"$75"},{"key":"C","text":"$100"},{"key":"D","text":"$150"}]'::jsonb, 'B', 'El límite diario estipulado para comidas es de $75.', 'Políticas corporativas de viajes y finanzas', 'easy', NULL),
  ('q7-21', 'p7-20', 7, 21, 'What type of expense is non-reimbursable?', '[{"key":"A","text":"Alcoholic drinks"},{"key":"B","text":"Taxi fares"},{"key":"C","text":"Hotel room taxes"},{"key":"D","text":"Train tickets"}]'::jsonb, 'A', 'Las bebidas alcohólicas están catalogadas como no reembolsables.', 'Políticas corporativas de viajes y finanzas', 'medium', NULL),
  ('q7-22', 'p7-20', 7, 22, 'Why did Julian attach itemized receipts?', '[{"key":"A","text":"The client requested copies"},{"key":"B","text":"The restaurant was overcharging"},{"key":"C","text":"It is a mandatory policy requirement"},{"key":"D","text":"To get a credit card bonus"}]'::jsonb, 'C', 'La política exige que todos los reclamos vengan con recibos desglosados del comercio.', 'Políticas corporativas de viajes y finanzas', 'medium', NULL),
